// ---------------------------------------------------------------- helpers
static String hex(const uint8_t *p, size_t n, const char *sep = "") {
  static const char *H = "0123456789abcdef";
  String s; s.reserve(n * (2 + strlen(sep)));
  for (size_t i = 0; i < n; i++) { s += H[p[i] >> 4]; s += H[p[i] & 15]; if (i + 1 < n) s += sep; }
  return s;
}
static String uuidStr(const uint8_t *u) {
  return hex(u, 4) + "-" + hex(u + 4, 2) + "-" + hex(u + 6, 2) + "-" + hex(u + 8, 2) + "-" + hex(u + 10, 6);
}
static const char *typeName(uint8_t t) { return t == 0x11 ? "outlet" : "meter"; }
static String jnum(uint32_t v) { return obi_na(v) ? String("null") : String((unsigned long)v); }
// power is a SIGNED int32 on the wire — it goes negative on feed-in/export. 0x7FFFFFFF still means n/a.
static String jnumS(uint32_t v) { return obi_na(v) ? String("null") : String((long)(int32_t)v); }
static const char *mqttStateText(int s) {
  switch (s) {
    case -4: return "timeout"; case -3: return "conn lost"; case -2: return "connect failed";
    case -1: return "disconnected"; case 0: return "connected"; case 1: return "bad protocol";
    case 2: return "bad client id"; case 3: return "unavailable"; case 4: return "bad credentials";
    case 5: return "unauthorized"; default: return "?";
  }
}
static String jstr(const char *s) { String o = "\""; for (; *s; s++) { if (*s == '"' || *s == '\\') o += '\\'; o += *s; } return o + "\""; }
// 0.0.0.0 is IPAddress's zero-value, returned e.g. by WiFi.dnsIP(1) when the network only hands out one DNS
// server -- report that as "unset" (empty string) rather than a literal "0.0.0.0" the Settings page would
// otherwise prefill into the DNS 2 field as if it meant something.
static String ipOrEmpty(IPAddress ip) { return ip == IPAddress(0, 0, 0, 0) ? String("") : ip.toString(); }

static String readersJson() {
  // Sort used readers by their 3-byte handle so the web UI always lists them in
  // the same, stable order (matches the shown "id").
  int order[MAX_READERS], n = 0;
  for (int i = 0; i < MAX_READERS; i++) if (readers[i].used) order[n++] = i;
  for (int a = 0; a < n - 1; a++)
    for (int b = 0; b < n - 1 - a; b++)
      if (memcmp(readers[order[b]].handle, readers[order[b + 1]].handle, 3) > 0) {
        int t = order[b]; order[b] = order[b + 1]; order[b + 1] = t;
      }

  String j = "[";
  bool first = true;
  for (int k = 0; k < n; k++) {
    Reader &r = readers[order[k]];
    if (!first) j += ",";
    first = false;
    uint32_t age = (millis() - r.lastSeenMs) / 1000;
    j += "{\"id\":\"" + hex(r.handle, 3) + "\"";
    j += ",\"name\":" + jstr(r.name);
    j += ",\"boxcfg\":" + jstr(r.boxcfg);
    j += ",\"uuid\":" + (r.haveUuid ? "\"" + uuidStr(r.uuid) + "\"" : "null");
    j += ",\"type\":\"" + String(typeName(r.devType)) + "\"";
    j += ",\"paired\":" + String(r.haveKey ? "true" : "false");
    j += ",\"assigned\":" + String(r.assigned ? "true" : "false");
    j += ",\"legacy\":" + String(r.legacy ? "true" : "false");
    j += ",\"softver\":" + String(r.softver) + ",\"hardver\":" + String(r.hardver);
    j += ",\"battery_mV\":" + String(r.battery_mV);
    j += ",\"rssi\":" + String((int)r.lastRssi);
    j += ",\"snr\":" + String(r.lastSnr, 1);
    j += ",\"infrared\":" + String((r.flags & 1) ? "true" : "false");
    j += ",\"import\":" + jnum(r.import_) + ",\"export\":" + jnum(r.export_) + ",\"power\":" + jnumS(r.power);
    j += ",\"power_calc\":" + jnumS(r.calcPower);
    j += ",\"has_data\":" + String(r.haveData ? "true" : "false");
    j += ",\"bootloader\":" + String(r.inBootloader ? "true" : "false");
    j += ",\"age_s\":" + String(age);
    j += ",\"interval\":" + String(r.setInterval);
    j += ",\"price_cent\":" + (r.priceCentOverride >= 0 ? String(r.priceCentOverride, 2) : String("null"));
    j += ",\"export_cent\":" + (r.exportCentOverride >= 0 ? String(r.exportCentOverride, 2) : String("null"));
    j += ",\"night_on\":" + String(r.nightTariffOn ? "true" : "false");
    j += ",\"night_start\":" + String(r.nightStartHour) + ",\"night_end\":" + String(r.nightEndHour);
    j += ",\"night_price_cent\":" + (r.nightPriceCent >= 0 ? String(r.nightPriceCent, 2) : String("null"));
    j += "}";
  }
  return j + "]";
}

// firmware build identity as a JSON object, shared by the web status endpoint and the MQTT gateway state.
static String fwJson() {
  return String("\"fw\":{\"version\":\"") + FW_VERSION + "\",\"build\":" + String(FW_BUILD_NUMBER) +
         ",\"target\":\"" + FW_BUILD_TARGET + "\",\"git\":\"" + FW_GIT_HASH +
         "\",\"date\":\"" + FW_BUILD_DATE + "\"}";
}

// Sanity-bounded: lower bound catches "never synced" (RTC still near the 1970 epoch); upper bound catches
// a garbage/corrupted SNTP reply being trusted as real (observed after rapid back-to-back self-OTA reboots
// during dev testing — a bogus reply once pushed the system clock to the year 343230). Without the upper
// bound, timeValid() would happily call that "synced" and every "now"/history-bucket read downstream would
// inherit the garbage value. 4102444800 = 2100-01-01 UTC — comfortably past any real deployment's lifetime.
static bool timeValid() { time_t t = time(nullptr); return t > 1735689600 && t < 4102444800; }

static String statusJson() {
  bool con = mqtt.connected();
  long lastPub = g_mqttLastPubMs ? (long)((millis() - g_mqttLastPubMs) / 1000) : -1;
  String j = "{";
  j += "\"gwid\":\"" + hex(GWID, 6) + "\"";
  j += "," + fwJson();
  j += ",\"gwid_ascii\":" + jstr(String((const char *)GWID).substring(0, 6).c_str());
  j += ",\"mac\":\"" + String(gwMac()) + "\",\"gw\":\"" + String(gwId()) + "\"";
  j += ",\"gw_custom_name\":" + jstr(g_gwName);   // custom display name (blank = using the technical default)
  { float t = gwTempC(); j += ",\"temp_c\":" + (isnan(t) ? String("null") : String(t, 1)); }
  j += ",\"pair_remaining_s\":" + String(gw_pair_remaining_s());
  j += ",\"uptime_s\":" + String(gw_uptime_s());
  // free_heap = total free (can be fragmented); max_alloc_heap = largest single block actually
  // allocatable right now. A reader-firmware OTA needs ONE contiguous malloc for the whole image
  // (see gw_ota_begin) -- max_alloc_heap is what decides whether that succeeds, not free_heap.
  j += ",\"free_heap\":" + String(ESP.getFreeHeap());
  j += ",\"max_alloc_heap\":" + String(ESP.getMaxAllocHeap());
  { bool tv = timeValid(); String tb = "-";
    if (tv) { time_t tnow = time(nullptr); struct tm lt; localtime_r(&tnow, &lt); char b[24];
              strftime(b, sizeof b, "%Y-%m-%d %H:%M:%S", &lt); tb = b; }
    // tv gates the formatted string itself (not just a separate flag) — a garbage/out-of-range clock (see
    // timeValid()) never gets rendered as a plausible-looking date; callers only trust "time" when time_valid.
    j += ",\"tz\":" + jstr(g_tz) + ",\"ntp\":" + jstr(g_ntp) + ",\"time\":\"" + tb + "\",\"time_valid\":" + String(tv ? "true" : "false"); }
  j += ",\"night_mode\":" + String(g_nightMode ? "true" : "false");
  j += ",\"num_fmt\":" + String(g_numFmt);   // 0=auto(follow lang) 1=EU (1.234,56) 2=US (1,234.56)
  j += ",\"hide_unbound\":" + String(g_hideUnbound ? "true" : "false");
  j += ",\"lora_sf\":" + String(g_loraSF);   // SF actually running since boot -- see /api/lora/sf
  j += ",\"wifi\":" + String(g_wifiOk ? "true" : "false");
  j += ",\"ip\":\"" + (g_wifiOk ? WiFi.localIP().toString() : String("-")) + "\"";
  j += ",\"wifi_rssi\":" + String(g_wifiOk ? WiFi.RSSI() : 0);
  j += ",\"ap\":{\"ssid\":" + jstr(apSsid()) + ",\"pass_set\":" + String(g_apPass[0] ? "true" : "false") + "}";
  j += ",\"static_ip\":{\"on\":" + String(g_staticIpOn ? "true" : "false") + ",\"ip\":" + jstr(g_staticIp) +
       ",\"gw\":" + jstr(g_staticGw) + ",\"sn\":" + jstr(g_staticSn) + ",\"dns1\":" + jstr(g_staticDns1) +
       ",\"dns2\":" + jstr(g_staticDns2) +
       // the CURRENTLY active values (DHCP-assigned or static, whichever is in effect right now) -- lets the
       // Settings page prefill the fields with today's real DHCP lease instead of blanks, so turning static
       // IP on for the first time starts from "what already works" rather than an empty form.
       ",\"cur_ip\":" + jstr(g_wifiOk ? ipOrEmpty(WiFi.localIP()).c_str() : "") +
       ",\"cur_sn\":" + jstr(g_wifiOk ? ipOrEmpty(WiFi.subnetMask()).c_str() : "") +
       ",\"cur_gw\":" + jstr(g_wifiOk ? ipOrEmpty(WiFi.gatewayIP()).c_str() : "") +
       ",\"cur_dns1\":" + jstr(g_wifiOk ? ipOrEmpty(WiFi.dnsIP(0)).c_str() : "") +
       ",\"cur_dns2\":" + jstr(g_wifiOk ? ipOrEmpty(WiFi.dnsIP(1)).c_str() : "") + "}";
  { uint32_t nextS = 0;   // seconds until the next periodic check -- 0 when auto-update is off/mid-update
    if (g_ghAuto) {
      uint64_t intervalMs = (uint64_t)g_ghIntervalH * 3600000ULL;
      if (g_ghLastCheckMs == 0xFFFFFFFF) nextS = (uint32_t)(intervalMs / 1000);   // not seeded yet -- full interval
      else { uint32_t elapsed = millis() - g_ghLastCheckMs;                       // (unsigned wrap-safe vs. millis() overflow)
             nextS = ((uint64_t)elapsed >= intervalMs) ? 0 : (uint32_t)((intervalMs - elapsed) / 1000); }
    }
    j += ",\"gh_auto\":{\"enabled\":" + String(g_ghAuto ? "true" : "false") + ",\"repo\":" + jstr(g_ghRepo) +
         ",\"interval_h\":" + String(g_ghIntervalH) + ",\"next_check_s\":" + String(nextS) +
         ",\"state\":" + String(g_ghState) + ",\"last_err\":" + jstr(g_ghLastError.c_str()) + "}";
  }
  { uint32_t nextS = 0;   // seconds until the next periodic FTP upload -- 0 when off/mid-upload, same shape as gh_auto
    if (g_ftpEnabled && g_ftpUseInterval) {
      uint64_t intervalMs = (uint64_t)g_ftpIntervalMin * 60000ULL;
      if (g_ftpLastRunMs == 0xFFFFFFFF) nextS = (uint32_t)(intervalMs / 1000);
      else { uint32_t elapsed = millis() - g_ftpLastRunMs;
             nextS = ((uint64_t)elapsed >= intervalMs) ? 0 : (uint32_t)((intervalMs - elapsed) / 1000); }
    }
    j += ",\"ftp\":{\"enabled\":" + String(g_ftpEnabled ? "true" : "false") + ",\"host\":" + jstr(g_ftpHost) +
         ",\"port\":" + String(g_ftpPort) + ",\"user\":" + jstr(g_ftpUser) + ",\"path\":" + jstr(g_ftpPath) +
         ",\"interval_min\":" + String(g_ftpIntervalMin) + ",\"next_check_s\":" + String(nextS) +
         ",\"use_interval\":" + String(g_ftpUseInterval ? "true" : "false") +
         ",\"use_time\":" + String(g_ftpUseTime ? "true" : "false") +
         ",\"hh\":" + String(g_ftpHour) + ",\"mm\":" + String(g_ftpMinute) + ",\"window\":" + String(g_ftpWindow) +
         ",\"busy\":" + String(g_ftpBusy ? "true" : "false") + ",\"last_result\":" + String(g_ftpLastResult) +
         ",\"last_run_s\":" + String(g_ftpLastRunS) + ",\"last_err\":" + jstr(g_ftpLastError.c_str()) +
         "}";
  }
  { size_t ht = 0, hu = 0; historySpace(ht, hu);
    size_t dt = 0, du = 0; dailySpace(dt, du);
    j += ",\"hist_fs\":{\"ok\":" + String(g_fsOk ? "true" : "false") +
         ",\"backend\":" + jstr(g_usingOtaHist ? "ota" : "userdata") +
         ",\"total\":" + String((uint32_t)ht) + ",\"used\":" + String((uint32_t)hu) +
         ",\"daily_total\":" + String((uint32_t)dt) + ",\"daily_used\":" + String((uint32_t)du) + "}"; }
  j += ",\"freq_mhz\":869.5,\"bw_khz\":500,\"sf\":" + String(g_liveSF);   // actually-active SF, not the boot-time default
  j += ",\"mqtt\":{\"host\":" + jstr(g_mqttHost) + ",\"port\":" + String(g_mqttPort);
  j += ",\"user\":" + jstr(g_mqttUser) + ",\"topic\":" + jstr(g_mqttTopic);
  j += ",\"tls\":" + String(g_mqttTls ? "true" : "false");
  j += ",\"ca_set\":" + String(g_mqttCa.length() ? "true" : "false");
  j += ",\"enabled\":" + String(g_mqttHost[0] ? "true" : "false");
  j += ",\"connected\":" + String(con ? "true" : "false");
  j += ",\"state\":" + jstr(mqttStateText(g_mqttState));
  j += ",\"pub_count\":" + String(g_mqttPubCount);
  j += ",\"last_pub_s\":" + String(lastPub) + "}";
  j += ",\"auth\":{\"enabled\":" + String(g_authUser[0] ? "true" : "false") + ",\"user\":" + jstr(g_authUser) + "}";
  // reader OTA status
  uint8_t ot[3] = {0}; gw_ota_target(ot);
  j += ",\"ota\":{\"active\":" + String(gw_ota_active() ? "true" : "false");
  j += ",\"target\":\"" + hex(ot, 3) + "\",\"size\":" + String(gw_ota_size());
  j += ",\"served\":" + String(gw_ota_progress()) + "}}";
  return j;
}

